def rotate_right(p):
    q = p.left
    p.left = q.right
    q.right = p
    return q

def rotate_left(p):
    q = p.right
    p.right = q.left
    q.left = p
    return q

def treap_insert(root, key):
    if root is None:
        return TreapNode(key)

    if key < root.key:
        root.left = treap_insert(root.left, key)
        if root.left.priority < root.priority:
            root = rotate_right(root)
    elif key > root.key:
        root.right = treap_insert(root.right, key)
        if root.right.priority < root.priority:
            root = rotate_left(root)
    # If equal, do nothing (no duplicates)
    return root

def treap_delete(root, key):
    if root is None:
        return None

    if key < root.key:
        root.left = treap_delete(root.left, key)
    elif key > root.key:
        root.right = treap_delete(root.right, key)
    else:
        # Found the node to delete
        if root.left is None:
            return root.right
        elif root.right is None:
            return root.left
        else:
            # Two children: rotate with smaller priority child
            if root.left.priority < root.right.priority:
                root = rotate_right(root)
                root.right = treap_delete(root.right, key)
            else:
                root = rotate_left(root)
                root.left = treap_delete(root.left, key)
    return root

def treap_find(root, key):
    while root is not None:
        if key == root.key:
            return True
        elif key < root.key:
            root = root.left
        else:
            root = root.right
    return False

def inorder(root, out):
