class Node:
    __slots__ = ("key", "priority", "left", "right")

    def __init__(self, key, priority):
        self.key = key
        self.priority = priority
        self.left = None
        self.right = None


class Treap:
    def __init__(self):
        self.root = None

    def right_rotate(self, t):
        s = t.left
        t.left = s.right
        s.right = t
        return s

    def left_rotate(self, t):
        s = t.right
        t.right = s.left
        s.left = t
        return s

    def insert(self, key, priority):
        self.root = self._insert(self.root, key, priority)

    def _insert(self, t, key, priority):
        if t is None:
            return Node(key, priority)

        if key == t.key:
            return t
        elif key < t.key:
            t.left = self._insert(t.left, key, priority)
            if t.left is not None and t.priority < t.left.priority:
                t = self.right_rotate(t)
        else:
            t.right = self._insert(t.right, key, priority)
            if t.right is not None and t.priority < t.right.priority:
                t = self.left_rotate(t)

        return t

    def find(self, key):
        t = self.root
        while t is not None:
            if key == t.key:
                return True
            elif key < t.key:
                t = t.left
            else:
                t = t.right
        return False

    def delete(self, key):
        self.root = self._delete(self.root, key)

    def _delete(self, t, key):
        if t is None:
            return None

        if key < t.key:
            t.left = self._delete(t.left, key)
        elif key > t.key:
            t.right = self._delete(t.right, key)
        else:
            if t.left is None and t.right is None:
                return None
            elif t.left is None:
                t = self.left_rotate(t)
                t.left = self._delete(t.left, key)
            elif t.right is None:
                t = self.right_rotate(t)
                t.right = self._delete(t.right, key)
            else:
                if t.left.priority > t.right.priority:
                    t = self.right_rotate(t)
                    t.right = self._delete(t.right, key)
                else:
                    t = self.left_rotate(t)
                    t.left = self._delete(t.left, key)

        return t

    def inorder(self):
        res = []
        self._inorder(self.root, res)
        return res

    def _inorder(self, t, res):
        if t is None:
            return
        self._inorder(t.left, res)
        res.append(t.key)
        self._inorder(t.right, res)

    def preorder(self):
        res = []
        self._preorder(self.root, res)
        return res

    def _preorder(self, t, res):
        if t is None:
            return
        res.append(t.key)
        self._preorder(t.left, res)
        self._preorder(t.right, res)


