import java.util.*;
import java.io.*;

public class Main {
    static int[] key = new int[200005];
    static int[] pri = new int[200005];
    static int[] left = new int[200005];
    static int[] right = new int[200005];
    static int root = 0;
    static int nodeCount = 0;

    static int newNode(int k, int p) {
        nodeCount++;
        key[nodeCount] = k;
        pri[nodeCount] = p;
        left[nodeCount] = 0;
        right[nodeCount] = 0;
        return nodeCount;
    }

    // split: keys <= k go to l, keys > k go to r
    static int[] split(int t, int k) {
        if (t == 0) return new int[]{0, 0};
        if (key[t] <= k) {
            int[] res = split(right[t], k);
            right[t] = res[0];
            return new int[]{t, res[1]};
        } else {
            int[] res = split(left[t], k);
            left[t] = res[1];
            return new int[]{res[0], t};
        }
    }

    static int merge(int l, int r) {
        if (l == 0) return r;
        if (r == 0) return l;
        if (pri[l] >= pri[r]) {
            right[l] = merge(right[l], r);
            return l;
        } else {
            left[r] = merge(l, left[r]);
            return r;
        }
    }

    static void insert(int k, int p) {
        int[] lr = split(root, k - 1);
        int newN = newNode(k, p);
        root = merge(merge(lr[0], newN), lr[1]);
    }

    static boolean find(int t, int k) {
        if (t == 0) return false;
        if (key[t] == k) return true;
        if (k < key[t]) return find(left[t], k);
        return find(right[t], k);
    }

    static void delete(int k) {
        int[] lr = split(root, k - 1);
        int[] mr = split(lr[1], k);
        root = merge(lr[0], mr[1]);
    }

    static StringBuilder sb = new StringBuilder();

    static void inorder(int t) {
        if (t == 0) return;
        inorder(left[t]);
        if (sb.length() > 0) sb.append(' ');
        sb.append(key[t]);
        inorder(right[t]);
    }

    static void preorder(int t) {
        if (t == 0) return;
        if (sb.length() > 0) sb.append(' ');
        sb.append(key[t]);
        preorder(left[t]);
        preorder(right[t]);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split("\\s+");
            if (parts[0].equals("insert")) {
                int k = Integer.parseInt(parts[1]);
                int p = Integer.parseInt(parts[2]);
                insert(k, p);
            } else if (parts[0].equals("find")) {
                int k = Integer.parseInt(parts[1]);
                pw.println(find(root, k) ? "yes" : "no");
            } else if (parts[0].equals("delete")) {
                int k = Integer.parseInt(parts[1]);
                delete(k);
            } else if (parts[0].equals("print")) {
                sb = new StringBuilder();
                inorder(root);
                pw.println(sb.toString());
                sb = new StringBuilder();
                preorder(root);
                pw.println(sb.toString());
            }
        }
        pw.flush();
    }
}

import java.util.*;

class TreapNode {
    int key, priority;
    TreapNode left, right;

    TreapNode(int key) {
        this.key = key;
        this.priority = (int) (Math.random() * 1_000_000);
        this.left = this.right = null;
    }
}

public class Main {
    private static TreapNode root;

    // Rotations
    private static TreapNode rotateRight(TreapNode p) {
        TreapNode q = p.left;
        p.left = q.right;
        q.right = p;
        return q;
    }

    private static TreapNode rotateLeft(TreapNode q) {
        TreapNode p = q.right;
        q.right = p.left;
        p.left = q;
        return p;
    }

    // Insert with recursion
    private static TreapNode insert(TreapNode node, int key) {
        if (node == null) return new TreapNode(key);

        if (key < node.key) {
            node.left = insert(node.left, key);
            if (node.left.priority > node.priority) {
                node = rotateRight(node);
            }
        } else if (key > node.key) {
            node.right = insert(node.right, key);
            if (node.right.priority > node.priority) {
                node = rotateLeft(node);
            }
        }
        // if equal, do nothing (no duplicates)
        return node;
    }

    // Delete with recursion
    private static TreapNode delete(TreapNode node, int key) {
        if (node == null) return null;

        if (key < node.key) {
            node.left = delete(node.left, key);
        } else if (key > node.key) {
            node.right = delete(node.right, key);
        } else {
            // found node to delete
            if (node.left == null) return node.right;
            if (node.right == null) return node.left;

            if (node.left.priority > node.right.priority) {
                node = rotateRight(node);
                node.right = delete(node.right, key);
            } else {
                node = rotateLeft(node);
                node.left = delete(node.left, key);
            }
        }
        return node;
    }

    // Search
    private static boolean search(TreapNode node, int key) {
        if (node == null) return false;
        if (key == node.key) return true;
        if (key < node.key) return search(node.left, key);
        return search(node.right, key);
    }

    // Inorder
    private static void inorder(TreapNode node, StringBuilder sb) {
        if (node == null) return;
        inorder(node.left, sb);
        sb.append(node.key).append(" ");
        inorder(node.right, sb);
    }

    // Preorder
    private static void preorder(TreapNode node, StringBuilder sb) {
        if (node == null) return;
        sb.append(node.key).append(" ");
        preorder(node.left, sb);
        preorder(node.right, sb);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        sc.nextLine();

        while (t-- > 0) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            String op = parts[0];

            switch (op) {
                case "I": {
                    int x = Integer.parseInt(parts[1]);
                    if (!search(root, x)) {
                        root = insert(root, x);
                    }
                    break;
                }
                case "D": {
                    int x = Integer.parseInt(parts[1]);
                    if (search(root, x)) {
                        root = delete(root, x);
                    }
                    break;
                }
                case "S": {
                    int x = Integer.parseInt(parts[1]);
                    System.out.println(x + " " + (search(root, x) ? "exists" : "not exists"));
                    break;
                }
                case "P": {
                    StringBuilder inorderStr = new StringBuilder();
                    StringBuilder preorderStr = new StringBuilder();
                    inorder(root, inorderStr);
                    preorder(root, preorderStr);
                    System.out.println(inorderStr.toString().trim());
                    System.out.println(preorderStr.toString().trim());
                    break;
                }
            }
        }
        sc.close();
    }
}

