        Node root;

        boolean find(int key) {
            Node cur = root;
            while (cur != null) {
                if (key == cur.key) return true;
                if (key < cur.key) cur = cur.left;
                else cur = cur.right;
            }
            return false;
        }

        Node rightRotate(Node t) {
            Node s = t.left;
            t.left = s.right;
            s.right = t;
            return s;
        }

        Node leftRotate(Node t) {
            Node s = t.right;
            t.right = s.left;
            s.left = t;
            return s;
        }

        Node insert(Node t, int key, int priority) {
            if (t == null) return new Node(key, priority);

            if (key == t.key) return t;

            if (key < t.key) {
                t.left = insert(t.left, key, priority);
                if (t.left != null && t.priority < t.left.priority) {
                    t = rightRotate(t);
                }
            } else {
                t.right = insert(t.right, key, priority);
                if (t.right != null && t.priority < t.right.priority) {
                    t = leftRotate(t);
                }
            }
            return t;
        }

        void insert(int key, int priority) {
            root = insert(root, key, priority);
        }

        Node delete(Node t, int key) {
            if (t == null) return null;

            if (key < t.key) {
                t.left = delete(t.left, key);
            } else if (key > t.key) {
                t.right = delete(t.right, key);
            } else {
                if (t.left == null && t.right == null) {
                    return null;
                } else if (t.left == null) {
                    t = leftRotate(t);
                    t.left = delete(t.left, key);
                } else if (t.right == null) {
                    t = rightRotate(t);
                    t.right = delete(t.right, key);
                } else {
                    if (t.left.priority > t.right.priority) {
                        t = rightRotate(t);
                        t.right = delete(t.right, key);
                    } else {
                        t = leftRotate(t);
                        t.left = delete(t.left, key);
                    }
                }
            }
            return t;
        }

        void delete(int key) {
            root = delete(root, key);
        }

        void inorder(Node t, StringBuilder sb) {
            if (t == null) return;
            inorder(t.left, sb);
            sb.append(' ').append(t.key);
            inorder(t.right, sb);
        }

        void preorder(Node t, StringBuilder sb) {
            if (t == null) return;
            sb.append(' ').append(t.key);
            preorder(t.left, sb);
            preorder(t.right, sb);
        }

        String inorderString() {
